SELECT r.id, r.record_id, r.report_no, r.version, r.status, r.summary, r.doctor_advice, r.generated_at, r.archived_at, r.deleted, r.created_at, r.created_by, r.updated_at, r.updated_by, s.name AS studentName, s.student_no AS studentNo, b.batch_name AS batchName FROM t_report r LEFT JOIN t_exam_record er ON r.record_id = er.id LEFT JOIN t_student s ON er.student_id = s.id LEFT JOIN t_exam_batch b ON er.batch_id = b.id WHERE r.deleted = 0
AND r.record_id = #{recordId}
AND er.student_id = #{studentId}
AND r.status = #{status}
ORDER BY r.generated_at DESC, r.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT r.report_no, s.student_no, s.name AS student_name, s.college, b.batch_name, r.summary, r.doctor_advice, r.generated_at FROM t_report r JOIN t_exam_record er ON r.record_id = er.id JOIN t_student s ON er.student_id = s.id JOIN t_exam_batch b ON er.batch_id = b.id WHERE r.deleted = 0
AND r.record_id = #{recordId}
AND r.status = #{status}
ORDER BY r.generated_at DESC, r.id DESC

SELECT COUNT(1)
FROM t_report
WHERE deleted = 0

    AND record_id = #{recordId}


    AND record_id IN (SELECT id FROM t_exam_record WHERE student_id = #{studentId})


    AND status = #{status}

